from PIL import Image, ImageDraw
im=Image.open('radiograph.jpg').convert('RGB')
def crop(name,a,b,fr=8):
    x0,y0,x1,y1=int(2444*a),int(1292*b[0]),int(2444*b[1]),int(1292*b[2])
    c=im.crop((x0,y0,x1,y1)); c=c.resize((c.width*fr,c.height*fr))
    d=ImageDraw.Draw(c)
    for i in range(0,101):
        if 2444*i/100<x0 or 2444*i/100>x1: continue
        x=int((2444*i/100-x0)*fr)
        if i%2==0: d.line([(x,0),(x,c.height)],fill=(255,0,0),width=1); d.text((x+2,3),str(i/100),fill=(255,255,0))
    for j in range(0,101):
        if 1292*j/100<y0 or 1292*j/100>y1: continue
        y=int((1292*j/100-y0)*fr)
        if j%2==0: d.line([(0,y),(c.width,y)],fill=(0,180,255),width=1); d.text((3,y+2),str(j/100),fill=(0,255,255))
    c.save(f'/tmp/{name}.png'); print(name,c.size)
